-- Dr. Poo private property intelligence D1 schema (initial migration)
-- Cloudflare D1: dr-poo-property-intelligence
-- No personal records or property exports belong in this repository.
CREATE TABLE IF NOT EXISTS source_registry (source_id TEXT PRIMARY KEY, agency TEXT NOT NULL, source_url TEXT NOT NULL, rights_status TEXT NOT NULL CHECK(rights_status IN ('pending','approved','restricted','rejected')), source_date TEXT, retrieved_at TEXT NOT NULL, checksum TEXT, schema_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS properties (property_id TEXT PRIMARY KEY, county TEXT NOT NULL CHECK(county IN ('Baker','Clay','Duval','Nassau','St. Johns')), parcel_key TEXT, address_line TEXT, city TEXT, postal_code TEXT, wastewater_class TEXT NOT NULL DEFAULT 'unknown', verification_status TEXT NOT NULL DEFAULT 'unverified', source_id TEXT NOT NULL REFERENCES source_registry(source_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(county,parcel_key));
CREATE TABLE IF NOT EXISTS septic_evidence (evidence_id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(property_id), source_id TEXT NOT NULL REFERENCES source_registry(source_id), permit_reference TEXT, source_document_url TEXT, source_page TEXT, system_category TEXT NOT NULL DEFAULT 'unknown', configuration_status TEXT NOT NULL DEFAULT 'unknown' CHECK(configuration_status IN ('proposed','permitted','as_built','inspected','field_verified','unknown')), tank_capacity_gallons INTEGER CHECK(tank_capacity_gallons IS NULL OR tank_capacity_gallons > 0), tank_count INTEGER CHECK(tank_count IS NULL OR tank_count > 0), design_flow_gpd REAL CHECK(design_flow_gpd IS NULL OR design_flow_gpd > 0), drainfield_type TEXT, drainfield_area_sqft REAL CHECK(drainfield_area_sqft IS NULL OR drainfield_area_sqft > 0), manufacturer TEXT, model TEXT, rated_treatment_capacity_gpd REAL CHECK(rated_treatment_capacity_gpd IS NULL OR rated_treatment_capacity_gpd > 0), installation_date TEXT, final_inspection_date TEXT, observed_at TEXT, reviewed_at TEXT, review_status TEXT NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','verified','rejected','conflicted')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_history (service_id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(property_id), service_type TEXT NOT NULL, service_date TEXT NOT NULL, evidence_id TEXT REFERENCES septic_evidence(evidence_id), source_id TEXT NOT NULL REFERENCES source_registry(source_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS prospects (prospect_id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(property_id), eligibility_basis TEXT NOT NULL, priority INTEGER CHECK(priority BETWEEN 1 AND 5), workflow_status TEXT NOT NULL DEFAULT 'review' CHECK(workflow_status IN ('review','qualified','contacted','closed','suppressed')), reviewed_at TEXT, evidence_id TEXT NOT NULL REFERENCES septic_evidence(evidence_id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS outreach_suppression (property_id TEXT PRIMARY KEY REFERENCES properties(property_id), reason TEXT NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_properties_county_class ON properties(county,wastewater_class);
CREATE INDEX IF NOT EXISTS idx_evidence_property_type ON septic_evidence(property_id,system_category,review_status);
CREATE INDEX IF NOT EXISTS idx_prospects_status ON prospects(workflow_status,priority);
CREATE INDEX IF NOT EXISTS idx_service_property_date ON service_history(property_id,service_date);
